scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_140'] || []

control 'CKV_AWS_140' do
  title 'Ensure that RDS global clusters are encrypted'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_rds_global_cluster resources that actually exist, enumerated
    through the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    A global cluster's encryption is fixed at creation and inherited by
    every secondary it replicates into. An unencrypted global cluster
    therefore writes plaintext storage in every region it reaches, and the
    only fix is to build a new one.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: storage_encrypted is true on the global cluster
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_rds_global_cluster:

      resource "aws_rds_global_cluster" "app" {
        global_cluster_identifier = "app-global"
        engine                    = "aurora-postgresql"
        engine_version            = "15.17"
        database_name             = "app"
        storage_encrypted         = true
        deletion_protection       = true
      }

    Note (aws_rds_global_cluster): There is no in-place fix and no CLI
    equivalent. StorageEncrypted is set when the global cluster is created and
    cannot be modified afterwards: remediation means creating an encrypted
    global cluster and migrating into it, which is a data move, not a
    configuration change.
  FIX

  tag checkov_id:            'CKV_AWS_140'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'custom'
  tag tf_resources:          %w[aws_rds_global_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/rds_global_cluster'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_rds_global_cluster', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
  # one with nothing in it. A missing SDK gem, a denied call or an unreachable
  # endpoint all end up here, and without this assertion they render as "no
  # assets" and the control reports Not Applicable: the worst case reported as
  # "does not apply here".
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe "aws_rds_global_cluster enumeration" do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:storage_encrypted].nil? }

  # `!unreadable.empty?` keeps the control APPLICABLE when the enumeration could
  # not be read. Without it, the single case the guard above exists for — every
  # region denied, so ZERO rows AND an error — makes `in_scope` empty, only_if
  # skips the whole control, and the guard is skipped along with it: impact 0.0
  # and one skipped result, which HDF rolls up as Not Applicable. A guard that
  # only_if suppresses is not a guard, and this one was suppressed in exactly
  # the state it was written to catch.
  applicable = !in_scope.empty? || !unreadable.empty?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_rds_global_cluster in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_rds_global_cluster #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:storage_encrypted] }
      it { should eq true }
    end
  end
end
